/**
 * The districts of each type that hold people in each Chicago ward.
 * Generated by `npm run build-district-map` (scripts/build-district-map.ts);
 * do not edit by hand. A ward lists a district when some populated 2020
 * census block of the ward has its interior point in it, so a ward only
 * lists districts where its residents live, split precincts included.
 * Built 2026-09-29 from:
 * - US House (120th Congress), IL Senate, IL House (2026 districts): Census
 *   TIGERweb tigerWMS_Current layers 54, 56, 58.
 * - Cook County commissioner, Board of Review, judicial subcircuit (2022
 *   map): Cook County GIS electionSrvcLite layers 12, 11, 13.
 * - Chicago Board of Education subdistricts 1a..10b: the General Assembly's
 *   ERSB_20_Sub_District_Map_FA1_SB_15 shapefile.
 * - Police districts: data.cityofchicago.org 24zt-jpfn (district 31, which
 *   has no district council, left out).
 * - Precincts (2025-): data.cityofchicago.org i8fv-xe4b.
 * - Populated 2020 census blocks: Census TIGERweb tigerWMS_Census2020
 *   layer 10.
 * A ward usually sits in several districts of a type, so a ward alone never
 * pins down one person's district; the address lookup on the server does.
 */

export interface Districts {
  usHouse: number;
  ilSenate: number;
  ilHouse: number;
  cookCommissioner: number;
  boardOfReview: number;
  subcircuit: number;
  /** '1a'..'10b' */
  schoolBoard: string;
  police: number;
}

export type WardDistricts = { [K in keyof Districts]: Districts[K][] };

